#include <stereoforge/daxa_dual_preprocess.hpp>
#include <iostream>
#include <stdexcept>
using namespace stereoforge;
void check(bool value,const char* what){if(!value)throw std::runtime_error(what);}
template<class F> void rejects(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}check(failed,"expected rejection");}
DaxaRectification grid(unsigned width,unsigned height,const char* id){DaxaRectification c;c.eye_width=6;c.source_height=5;c.stride_bytes=25;c.width=width;c.height=height;c.original_identity="original";c.rectified_identity=id;for(auto& m:c.maps)m.resize(width*height);for(unsigned eye=0;eye<2;++eye)for(unsigned y=0;y<height;++y)for(unsigned x=0;x<width;++x){size_t i=y*width+x;c.maps[2*eye][i]=float(x)+.25f;c.maps[2*eye+1][i]=float(y)+.125f;}return c;}
CaptureLease source(unsigned seed){auto s=std::make_shared<CaptureFrame>();s->source_width=12;s->height=5;s->stride_bytes=25;s->calibration_identity="original";s->frame_id=seed;s->packed_yuyv.resize(125);for(size_t i=0;i<s->packed_yuyv.size();++i)s->packed_yuyv[i]=uint8_t(i*17+seed*3);return s;}
int main(int argc,char**argv){try{auto full=grid(6,4,"full"),coarse=grid(3,2,"coarse");auto a=source(1),b=source(2);auto af=daxa_preprocess_reference(*a,full),ac=daxa_preprocess_reference(*a,coarse),bf=daxa_preprocess_reference(*b,full),bc=daxa_preprocess_reference(*b,coarse);check(af.planes[0]==ac.planes[0]&&af.planes[0]!=bf.planes[0],"distinct inputs retain original RGB");
if(argc>1&&std::string(argv[1])=="--gpu"){auto ctx=std::make_shared<DaxaFoundation>(true);{DaxaDualPreprocess dual(full,coarse,2,ctx);auto invalid=std::make_shared<CaptureFrame>(*a);invalid->calibration_identity="wrong";rejects([&]{dual.enqueue(invalid);});auto one=dual.enqueue(a),two=dual.enqueue(b);check(one.full.source()==a&&one.coarse.source()==a&&one.full.calibration()->rectified_identity=="full"&&one.coarse.calibration()->rectified_identity=="coarse","source and calibration preserved");check(one.full.plane(DaxaPreprocessPlane::OriginalLeft).buffer()==one.coarse.plane(DaxaPreprocessPlane::OriginalLeft).buffer(),"original shared");rejects([&]{dual.enqueue(a);});check(dual.readback(one.full).planes==af.planes&&dual.readback(one.coarse).planes==ac.planes&&dual.readback(two.full).planes==bf.planes&&dual.readback(two.coarse).planes==bc.planes,"all planes match independent scalar reference");DaxaPreprocess baseline_full(full,1,ctx),baseline_coarse(coarse,1,ctx);auto ref_full=baseline_full.enqueue(a),ref_coarse=baseline_coarse.enqueue(a);check(dual.readback(one.full).planes==baseline_full.readback(ref_full).planes&&dual.readback(one.coarse).planes==baseline_coarse.readback(ref_coarse).planes,"both grids exactly match independent GPU preprocessors");auto held=one.coarse;one={};rejects([&]{dual.enqueue(a);});held={};auto three=dual.enqueue(a);check(dual.readback(three.full).planes==af.planes,"released slot recycled");}ctx->close();check(ctx->validation_errors==0&&ctx->validation_warnings==0,"validation through teardown");}
std::cout<<"dual preprocess contracts passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
